/**
 * Regression tests for periodEngine.js - the new, deterministic,
 * LLM-independent date-period resolver (Part 1 of the Stock Group
 * analytics foundation).
 *
 * Every expected value below was independently computed (printed via a
 * throwaway script, cross-checked by hand against the calendar) BEFORE
 * being hardcoded here - never generated by calling the function under
 * test and trusting its own output. All comparisons use .toISOString()
 * so results are unambiguous regardless of the machine's local
 * timezone.
 *
 * No live Tally connection, no MongoDB, no Anthropic API - pure
 * function tests only.
 *
 * Run: node verify-period-engine.js
 */

const periodEngine = require("./src/services/analytics/periodEngine");

let pass = 0;
let fail = 0;

function check(id, description, actual, expected) {
  const ok = JSON.stringify(actual) === JSON.stringify(expected);
  console.log(`${ok ? "PASS" : "FAIL"} | ${id} - ${description}${ok ? "" : `\n      expected: ${JSON.stringify(expected)}\n      actual:   ${JSON.stringify(actual)}`}`);
  if (ok) pass += 1; else fail += 1;
}

function iso(period) {
  return {
    from: period.from.toISOString(),
    to: period.to.toISOString(),
    label: period.label,
    isPartial: period.isPartial,
  };
}

function isoComparison(comparison) {
  if (comparison === null) return null;
  return { from: comparison.from.toISOString(), to: comparison.to.toISOString() };
}

// Wednesday, mid-week, mid-quarter(-ish), mid-month, mid-FY reference date.
const REF_WED = new Date(2026, 8, 23, 10, 30, 0); // 23 Sep 2026, 10:30am local
// Within Q1 (Jan-Mar) and within FY 2025-26 (since Jan < April) - exercises
// the year-boundary quarter/FY shift paths current_quarter/previous_quarter
// etc. don't hit with REF_WED.
const REF_JAN = new Date(2026, 0, 15, 9, 0, 0); // 15 Jan 2026
// A real leap day - exercises the Feb-29-shifted-into-a-non-leap-year case.
const REF_LEAP = new Date(2024, 1, 29, 10, 0, 0); // 29 Feb 2024

console.log("=== 9. Period resolution for every supported period kind ===");

for (const kind of periodEngine.PERIOD_KINDS) {
  if (kind === "custom" || kind === "specific_fy") continue; // need options, tested separately below
  const result = periodEngine.resolvePeriod(kind, REF_WED);
  check(`resolve-${kind}`, `resolvePeriod("${kind}") returns a valid {from,to,label,isPartial} with from <= to`,
    result.from <= result.to && typeof result.label === "string" && typeof result.isPartial === "boolean", true);
}

console.log("\n=== today / yesterday (exact) ===");
check("today-exact", "today: from=start of day, to=referenceDate, isPartial=true (10:30am is not the day's last instant)",
  iso(periodEngine.resolvePeriod("today", REF_WED)),
  { from: "2026-09-22T18:30:00.000Z", to: "2026-09-23T05:00:00.000Z", label: "Today", isPartial: true });
check("today-comparison", "today's comparison is exactly yesterday (full day)",
  isoComparison(periodEngine.resolveComparisonPeriod("today", REF_WED)),
  { from: "2026-09-21T18:30:00.000Z", to: "2026-09-22T18:29:59.999Z" });

check("yesterday-exact", "yesterday: a complete day, isPartial=false",
  iso(periodEngine.resolvePeriod("yesterday", REF_WED)),
  { from: "2026-09-21T18:30:00.000Z", to: "2026-09-22T18:29:59.999Z", label: "Yesterday", isPartial: false });
check("yesterday-comparison", "yesterday's comparison is the day before yesterday",
  isoComparison(periodEngine.resolveComparisonPeriod("yesterday", REF_WED)),
  { from: "2026-09-20T18:30:00.000Z", to: "2026-09-21T18:29:59.999Z" });

console.log("\n=== current week / previous week ===");
check("current-week-exact", "current_week: Monday of this week through referenceDate",
  iso(periodEngine.resolvePeriod("current_week", REF_WED)),
  { from: "2026-09-20T18:30:00.000Z", to: "2026-09-23T05:00:00.000Z", label: "Current week to date", isPartial: true });
check("current-week-comparison", "current_week comparison is the same weekday range, 7 days earlier",
  isoComparison(periodEngine.resolveComparisonPeriod("current_week", REF_WED)),
  { from: "2026-09-13T18:30:00.000Z", to: "2026-09-16T05:00:00.000Z" });
check("previous-week-exact", "previous_week: the complete prior Mon-Sun week",
  iso(periodEngine.resolvePeriod("previous_week", REF_WED)),
  { from: "2026-09-13T18:30:00.000Z", to: "2026-09-20T18:29:59.999Z", label: "Previous week (complete)", isPartial: false });
check("previous-week-comparison", "previous_week comparison is the week before that",
  isoComparison(periodEngine.resolveComparisonPeriod("previous_week", REF_WED)),
  { from: "2026-09-06T18:30:00.000Z", to: "2026-09-13T18:29:59.999Z" });

console.log("\n=== 11. Quarter boundary cases ===");
check("current-quarter-exact", "current_quarter (Sep, Q3 Jul-Sep): Jul 1 through referenceDate",
  iso(periodEngine.resolvePeriod("current_quarter", REF_WED)),
  { from: "2026-06-30T18:30:00.000Z", to: "2026-09-23T05:00:00.000Z", label: "Current quarter to date", isPartial: true });
check("current-quarter-comparison", "current_quarter comparison is the same date-range in Q2 (not clamped to 1 month)",
  isoComparison(periodEngine.resolveComparisonPeriod("current_quarter", REF_WED)),
  { from: "2026-03-31T18:30:00.000Z", to: "2026-06-23T05:00:00.000Z" });
check("previous-quarter-exact", "previous_quarter (from Sep ref): the complete Q2 (Apr-Jun)",
  iso(periodEngine.resolvePeriod("previous_quarter", REF_WED)),
  { from: "2026-03-31T18:30:00.000Z", to: "2026-06-30T18:29:59.999Z", label: "Previous quarter (complete)", isPartial: false });
check("previous-quarter-comparison", "previous_quarter comparison is the complete Q1 before it",
  isoComparison(periodEngine.resolveComparisonPeriod("previous_quarter", REF_WED)),
  { from: "2025-12-31T18:30:00.000Z", to: "2026-03-31T18:29:59.999Z" });

console.log("\n--- Quarter year-boundary case (reference in Q1) ---");
check("current-quarter-q1-exact", "current_quarter from a Jan reference (Q1 Jan-Mar): Jan 1 through referenceDate",
  iso(periodEngine.resolvePeriod("current_quarter", REF_JAN)),
  { from: "2025-12-31T18:30:00.000Z", to: "2026-01-15T03:30:00.000Z", label: "Current quarter to date", isPartial: true });
check("previous-quarter-q1-exact", "previous_quarter from a Jan reference correctly rolls back a full YEAR to Q4 (Oct-Dec) of the prior year",
  iso(periodEngine.resolvePeriod("previous_quarter", REF_JAN)),
  { from: "2025-09-30T18:30:00.000Z", to: "2025-12-31T18:29:59.999Z", label: "Previous quarter (complete)", isPartial: false });
check("previous-quarter-q1-comparison", "previous_quarter's own comparison (from a Jan reference) is Q3 of the prior year",
  isoComparison(periodEngine.resolveComparisonPeriod("previous_quarter", REF_JAN)),
  { from: "2025-06-30T18:30:00.000Z", to: "2025-09-30T18:29:59.999Z" });

console.log("\n=== 10. FY boundary cases (Apr 1 -> Mar 31) ===");
check("current-fy-exact", "current_fy (Sep ref, FY 2026-27): Apr 1 2026 through referenceDate",
  iso(periodEngine.resolvePeriod("current_fy", REF_WED)),
  { from: "2026-03-31T18:30:00.000Z", to: "2026-09-23T05:00:00.000Z", label: "FY 2026-27 (to date)", isPartial: true });
check("current-fy-comparison", "current_fy comparison is the same date-range one FY earlier",
  isoComparison(periodEngine.resolveComparisonPeriod("current_fy", REF_WED)),
  { from: "2025-03-31T18:30:00.000Z", to: "2025-09-23T05:00:00.000Z" });
check("previous-fy-exact", "previous_fy (from Sep 2026 ref): the complete FY 2025-26",
  iso(periodEngine.resolvePeriod("previous_fy", REF_WED)),
  { from: "2025-03-31T18:30:00.000Z", to: "2026-03-31T18:29:59.999Z", label: "FY 2025-26 (complete)", isPartial: false });
check("previous-fy-comparison", "previous_fy comparison is the complete FY before that (2024-25)",
  isoComparison(periodEngine.resolveComparisonPeriod("previous_fy", REF_WED)),
  { from: "2024-03-31T18:30:00.000Z", to: "2025-03-31T18:29:59.999Z" });
check("current-fy-jan-ref", "current_fy from a Jan reference correctly resolves to FY 2025-26 (Jan is before April, so it belongs to the PRIOR calendar year's FY)",
  iso(periodEngine.resolvePeriod("current_fy", REF_JAN)),
  { from: "2025-03-31T18:30:00.000Z", to: "2026-01-15T03:30:00.000Z", label: "FY 2025-26 (to date)", isPartial: true });

console.log("\n--- specific_fy ---");
check("specific-fy-complete", 'specific_fy("2025-26") from a Sep 2026 reference (already fully in the past): complete, not partial',
  iso(periodEngine.resolvePeriod("specific_fy", REF_WED, { fy: "2025-26" })),
  { from: "2025-03-31T18:30:00.000Z", to: "2026-03-31T18:29:59.999Z", label: "FY 2025-26 (complete)", isPartial: false });
check("specific-fy-complete-comparison", "specific_fy(2025-26) comparison is the FY immediately before it",
  isoComparison(periodEngine.resolveComparisonPeriod("specific_fy", REF_WED, { fy: "2025-26" })),
  { from: "2024-03-31T18:30:00.000Z", to: "2025-03-31T18:29:59.999Z" });
check("specific-fy-current-is-partial", 'specific_fy("2026-27") from a Sep 2026 reference (still ongoing): partial',
  periodEngine.resolvePeriod("specific_fy", REF_WED, { fy: "2026-27" }).isPartial, true);

console.log("\n--- parseFinancialYearInput format acceptance / rejection ---");
check("fy-parse-number", "accepts a plain start-year number", periodEngine.parseFinancialYearInput(2025), 2025);
check("fy-parse-label", 'accepts "FY 2025-26"', periodEngine.parseFinancialYearInput("FY 2025-26"), 2025);
check("fy-parse-bare", 'accepts "2025-26" (no "FY" prefix)', periodEngine.parseFinancialYearInput("2025-26"), 2025);
check("fy-parse-lowercase-no-space", 'accepts "fy2025-26" (lowercase, no space)', periodEngine.parseFinancialYearInput("fy2025-26"), 2025);
check("fy-parse-4digit-end", 'accepts "FY 2025-2026" (4-digit end year)', periodEngine.parseFinancialYearInput("FY 2025-2026"), 2025);
{
  let threw = false;
  try { periodEngine.parseFinancialYearInput("FY 2025-27"); } catch { threw = true; }
  check("fy-parse-inconsistent-span-rejected", '"FY 2025-27" (not a real one-year span) is rejected, not silently misparsed', threw, true);
}
{
  let threw = false;
  try { periodEngine.parseFinancialYearInput("not a fy"); } catch { threw = true; }
  check("fy-parse-garbage-rejected", "unparseable input throws rather than defaulting to something", threw, true);
}

console.log("\n=== 12. Leap-year / date boundary cases ===");
check("leap-day-current-fy", "current_fy from a real leap day (29 Feb 2024) resolves correctly (FY 2023-24, since Feb < April)",
  iso(periodEngine.resolvePeriod("current_fy", REF_LEAP)),
  { from: "2023-03-31T18:30:00.000Z", to: "2024-02-29T04:30:00.000Z", label: "FY 2023-24 (to date)", isPartial: true });
check("leap-day-comparison-clamped-not-rolled", "current_fy comparison for a leap-day reference clamps to 28 Feb of the non-leap prior year, instead of silently rolling to 1 Mar (the bug in a naive new Date(y,m,29) construction)",
  isoComparison(periodEngine.resolveComparisonPeriod("current_fy", REF_LEAP)),
  { from: "2022-03-31T18:30:00.000Z", to: "2023-02-28T04:30:00.000Z" });
{
  // Directly exercise the raw rollover this guards against, independent
  // of periodEngine's own logic - a naive "new Date(y, m, day)" shift of
  // 29 Feb into a non-leap year.
  const naive = new Date(2023, 1, 29); // JS auto-rolls Feb 29 in a non-leap year
  check("leap-day-naive-Date-does-roll-to-march", "sanity check: confirms the underlying JS behavior being guarded against is real (naive construction rolls into March)",
    naive.getMonth(), 2 /* March, 0-indexed - proves the roll-over actually happens */);
}
check("safeShiftYears-leap-clamp", "safeShiftYears(29 Feb 2024, -1) clamps to 28 Feb 2023, not 1 Mar 2023",
  periodEngine.safeShiftYears(new Date(2024, 1, 29, 10, 0, 0), -1).toISOString(),
  new Date(2023, 1, 28, 10, 0, 0).toISOString());
check("safeShiftMonths-month-length-clamp", "safeShiftMonths(31 Dec, -3) clamps to 30 Sep (Sep has 30 days), not rolling into October",
  periodEngine.safeShiftMonths(new Date(2026, 11, 31, 10, 0, 0), -3).toISOString(),
  new Date(2026, 8, 30, 10, 0, 0).toISOString());

console.log("\n=== 13. Custom date ranges ===");
check("custom-exact", "custom(2025-01-01, 2025-01-31) resolves to exact day-bounded range",
  iso(periodEngine.resolvePeriod("custom", REF_WED, { from: "2025-01-01", to: "2025-01-31" })),
  { from: "2024-12-31T18:30:00.000Z", to: "2025-01-31T18:29:59.999Z", label: "Custom range", isPartial: false });
check("custom-comparison-null", "custom has no natural comparison period (null, not guessed)",
  periodEngine.resolveComparisonPeriod("custom", REF_WED, { from: "2025-01-01", to: "2025-01-31" }), null);
{
  let threw = false;
  try { periodEngine.resolvePeriod("custom", REF_WED, {}); } catch { threw = true; }
  check("custom-missing-bounds-throws", "custom without from/to throws rather than silently defaulting", threw, true);
}

console.log("\n=== 14. Comparison-period correctness (other kinds) ===");
check("same-month-last-year-comparison-null", "same_month_last_year has no further comparison (it IS already the comparison target for current_month)",
  periodEngine.resolveComparisonPeriod("same_month_last_year", REF_WED), null);
check("current-month-comparison-reuses-existing", "current_month's comparison is exactly dateRanges.previousMonthSameRange (reused, not reimplemented)",
  isoComparison(periodEngine.resolveComparisonPeriod("current_month", REF_WED)),
  (() => { const p = require("./src/services/analytics/dateRanges").previousMonthSameRange(REF_WED); return { from: p.from.toISOString(), to: p.to.toISOString() }; })());
check("previous-month-comparison", "previous_month's comparison is the complete month before that (Aug 2026's comparison is Jul 2026)",
  isoComparison(periodEngine.resolveComparisonPeriod("previous_month", REF_WED)),
  { from: "2026-06-30T18:30:00.000Z", to: "2026-07-31T18:29:59.999Z" });
check("ytd-comparison", "ytd's comparison is the same calendar-YTD range one year earlier",
  isoComparison(periodEngine.resolveComparisonPeriod("ytd", REF_WED)),
  { from: "2024-12-31T18:30:00.000Z", to: "2025-09-23T05:00:00.000Z" });
check("last-7-days-comparison-non-overlapping", "last_7_days comparison is the immediately preceding, non-overlapping 7-day window",
  isoComparison(periodEngine.resolveComparisonPeriod("last_7_days", REF_WED)),
  { from: "2026-09-09T18:30:00.000Z", to: "2026-09-16T18:29:59.999Z" });

console.log("\n=== resolvePeriodWithComparison: single-call shape ===");
{
  const combined = periodEngine.resolvePeriodWithComparison("current_month", REF_WED);
  check("with-comparison-has-all-4-fields", "resolvePeriodWithComparison returns from/to/comparisonFrom/comparisonTo together",
    ["from", "to", "comparisonFrom", "comparisonTo"].every((k) => k in combined), true);
}
{
  const combined = periodEngine.resolvePeriodWithComparison("custom", REF_WED, { from: "2025-01-01", to: "2025-01-31" });
  check("with-comparison-omits-fields-when-null", "resolvePeriodWithComparison omits comparisonFrom/comparisonTo entirely when there's no natural comparison (custom range)",
    "comparisonFrom" in combined || "comparisonTo" in combined, false);
}

console.log("\n=== Unknown period kind ===");
{
  let threw = false;
  try { periodEngine.resolvePeriod("not_a_real_kind", REF_WED); } catch { threw = true; }
  check("unknown-kind-throws", "an unrecognized period kind throws rather than silently returning something", threw, true);
}

console.log(`\n${pass} passed, ${fail} failed, ${pass + fail} total`);
process.exit(fail > 0 ? 1 : 0);
